import unittest
from retry import should_retry

class RetryChecks(unittest.TestCase):
    def test_below_limit(self):
        self.assertIs(should_retry(1, 3), True)
    def test_over_limit(self):
        self.assertIs(should_retry(4, 3), False)
    def test_permanent_failure(self):
        self.assertIs(should_retry(0, 3, permanent=True), False)
